// ===== CONFIGURAÇÃO =====
var CODIGOS_IGNORADOS = [];         // códigos de produto fora da análise (ex.: serviços)
var MAX_PRODUTOS_EMAIL = 20;        // maiores CMVs listados no e-mail
var MAX_BYTES_DETALHE = 900000;     // acima disso a planilha recebe só os subtotais mensais
// ===== FUNÇÕES =====
var AC = { 'á': 'a', 'à': 'a', 'â': 'a', 'ã': 'a', 'ä': 'a', 'é': 'e', 'è': 'e', 'ê': 'e', 'í': 'i', 'ì': 'i', 'î': 'i', 'ó': 'o', 'ò': 'o', 'ô': 'o', 'õ': 'o', 'ö': 'o', 'ú': 'u', 'ù': 'u', 'û': 'u', 'ü': 'u', 'ç': 'c' };
var MARCAS = ['data_venda', 'produto'];
function chave(k) {
  var s = String(k).trim().toLowerCase(), o = '';
  for (var i = 0; i < s.length; i++) { var c = s.charAt(i); c = AC[c] || c; o += (c === ' ' || c === '-' || c === '.') ? '_' : c; }
  return o;
}
function normalizar(o) { var r = {}; for (var k in o) r[chave(k)] = o[k]; return r; }
function ehLinha(o) { var n = normalizar(o); for (var i = 0; i < MARCAS.length; i++) { if (n[MARCAS[i]] !== undefined) return n; } return null; }
function coletar(v, out, nivel) {
  if (v === null || v === undefined || nivel > 8) return;
  if (typeof v === 'string') {
    var t = v.trim();
    if (t.charAt(0) === '[' || t.charAt(0) === '{') { try { coletar(JSON.parse(t), out, nivel + 1); } catch (e) {} }
    return;
  }
  if (Array.isArray(v)) { for (var i = 0; i < v.length; i++) coletar(v[i], out, nivel + 1); return; }
  if (typeof v !== 'object') return;
  var linha = ehLinha(v);
  if (linha) { out.push(linha); return; }
  var cols = null, mat = null;
  for (var k in v) {
    var x = v[k];
    if (Array.isArray(x) && x.length && typeof x[0] === 'string' && !cols) cols = x;
    else if (Array.isArray(x) && x.length && Array.isArray(x[0]) && !mat) mat = x;
  }
  if (cols && mat) {
    for (var r = 0; r < mat.length; r++) { var ob = {}; for (var c = 0; c < cols.length; c++) ob[cols[c]] = mat[r][c]; coletar(ob, out, nivel + 1); }
    return;
  }
  for (var k2 in v) coletar(v[k2], out, nivel + 1);
}
function num(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return v;
  var s = String(v).trim();
  if (s.indexOf(',') >= 0) s = s.split('.').join('').replace(',', '.');
  var n = parseFloat(s); return isNaN(n) ? 0 : n;
}
function vazio(v) { return v === null || v === undefined || String(v).trim() === ''; }
function dia(v) {
  if (vazio(v)) return null;
  var s = String(v).trim().split(' ')[0].split('T')[0];
  if (s.indexOf('/') > 0) { var p = s.split('/'); if (p.length === 3) s = p[2] + '-' + ('0' + p[1]).slice(-2) + '-' + ('0' + p[0]).slice(-2); }
  var d = new Date(s + 'T00:00:00Z'); return isNaN(d.getTime()) ? null : d;
}
function iso(d) { return d.toISOString().substring(0, 10); }
function br(d) { var s = iso(d).split('-'); return s[2] + '/' + s[1] + '/' + s[0]; }
function mesBr(m) { var s = m.split('-'); return s[1] + '/' + s[0]; }
function r2(n) { return Math.round(n * 100) / 100; }
function pct(lucro, venda) { return venda > 0 ? r2(lucro / venda * 100) : 0; }
function brl(n) { var s = Math.abs(n).toFixed(2).split('.'), i = s[0], o = ''; while (i.length > 3) { o = '.' + i.slice(-3) + o; i = i.slice(0, -3); } return (n < 0 ? '-' : '') + 'R$ ' + i + o + ',' + s[1]; }
function txt(v) { return vazio(v) ? '' : String(v).trim(); }
function esc(v) { return txt(v).split('&').join('&amp;').split('<').join('&lt;'); }
// ===== PERÍODO SOLICITADO =====
var hoje = new Date($today + 'T00:00:00Z');
var entrada = {};
try { entrada = $node['Receber período'].json || {}; } catch (e) { entrada = {}; }
var ini = null, fim = null, erro = '';
if (!vazio(entrada.mes)) {
  var t = String(entrada.mes).trim();
  if (t.indexOf('/') > 0) { var q = t.split('/'); t = q[1] + '-' + q[0]; }
  var pa = t.split('-'), ano = parseInt(pa[0], 10), mes = parseInt(pa[1], 10);
  if (ano > 2000 && mes >= 1 && mes <= 12) { ini = new Date(Date.UTC(ano, mes - 1, 1)); fim = new Date(Date.UTC(ano, mes, 0)); }
} else if (!vazio(entrada.data_inicial) || !vazio(entrada.data_final)) {
  ini = dia(entrada.data_inicial); fim = dia(entrada.data_final);
} else {
  ini = new Date(Date.UTC(hoje.getUTCFullYear(), hoje.getUTCMonth() - 1, 1));
  fim = new Date(Date.UTC(hoje.getUTCFullYear(), hoje.getUTCMonth(), 0));
}
if (!ini || !fim || ini.getTime() > fim.getTime()) {
  erro = 'Período inválido. Envie {"mes": "AAAA-MM"} ou {"data_inicial": "AAAA-MM-DD", "data_final": "AAAA-MM-DD"} (também aceita DD/MM/AAAA). Sem corpo, usa o mês anterior completo.';
}
// ===== BASE DE VENDAS =====
var registros = [];
items.forEach(function (it) { coletar(it.json, registros, 0); });
var vendas = registros.filter(function (r) { return r.data_venda !== undefined && r.produto !== undefined; });
var baseIni = null, baseFim = null;
vendas.forEach(function (v) {
  var d = dia(v.data_venda); if (!d) return;
  if (!baseIni || d.getTime() < baseIni.getTime()) baseIni = d;
  if (!baseFim || d.getTime() > baseFim.getTime()) baseFim = d;
});
// ===== CÁLCULO =====
var grupos = {};
var dev = { linhas: 0, valor: 0 };
var linhasSemCusto = 0, linhasPeriodo = 0;
if (!erro) {
  vendas.forEach(function (v) {
    var d = dia(v.data_venda);
    if (!d || d.getTime() < ini.getTime() || d.getTime() > fim.getTime()) return;
    var cod = txt(v.produto);
    if (CODIGOS_IGNORADOS.indexOf(cod) >= 0) return;
    var qtd = num(v.quantidade);
    if (qtd < 0) { dev.linhas++; dev.valor += num(v.total_venda); return; }
    if (qtd === 0) return;
    var venda = num(v.total_venda), cmv = 0, semCusto = false;
    if (!vazio(v.total_custo)) cmv = num(v.total_custo);
    else if (!vazio(v.custo_unitario)) cmv = qtd * num(v.custo_unitario);
    else { semCusto = true; }
    var m = iso(d).substring(0, 7);
    var cnpj = txt(v._cnpjorigem);
    var emp = txt(v._razaoorigem).split('  ').join(' ').split('  ').join(' ');
    var k = m + '|' + cnpj + '|' + cod;
    if (!grupos[k]) grupos[k] = { mes: m, emp: emp, cod: cod, nome: txt(v.nomproduto), grupo: txt(v.grupo), subgrupo: txt(v.subgrupo), qtd: 0, venda: 0, cmv: 0, linhas: 0, semCusto: 0 };
    var g = grupos[k];
    g.qtd += qtd; g.venda += venda; g.cmv += cmv; g.linhas++;
    if (semCusto) { g.semCusto++; linhasSemCusto++; }
    linhasPeriodo++;
  });
}
var listaG = Object.keys(grupos).map(function (k) { return grupos[k]; });
listaG.sort(function (a, b) { if (a.mes !== b.mes) return a.mes < b.mes ? -1 : 1; if (a.emp !== b.emp) return a.emp < b.emp ? -1 : 1; return b.cmv - a.cmv; });
var mesesOrdem = [], porMes = {}, T = { venda: 0, cmv: 0, lucro: 0 };
listaG.forEach(function (g) {
  if (!porMes[g.mes]) { porMes[g.mes] = { mes: g.mes, venda: 0, cmv: 0 }; mesesOrdem.push(g.mes); }
  porMes[g.mes].venda += g.venda; porMes[g.mes].cmv += g.cmv;
  T.venda += g.venda; T.cmv += g.cmv;
});
T.lucro = T.venda - T.cmv;
// ===== TOTAIS POR EMPRESA =====
var porEmp = {}, porMesEmp = {};
listaG.forEach(function (g) {
  if (!porEmp[g.emp]) porEmp[g.emp] = { emp: g.emp, venda: 0, cmv: 0, produtos: {} };
  porEmp[g.emp].venda += g.venda; porEmp[g.emp].cmv += g.cmv; porEmp[g.emp].produtos[g.cod] = true;
  var km = g.mes + '|' + g.emp;
  if (!porMesEmp[km]) porMesEmp[km] = { venda: 0, cmv: 0 };
  porMesEmp[km].venda += g.venda; porMesEmp[km].cmv += g.cmv;
});
var empresasOrdem = Object.keys(porEmp).sort(function (a, b) { return porEmp[b].cmv - porEmp[a].cmv; });
function curta(e) { return txt(e).split(' ')[0]; }
var porProd = {};
listaG.forEach(function (g) {
  var k = g.emp + '|' + g.cod;
  if (!porProd[k]) porProd[k] = { cod: g.cod, nome: g.nome, emp: g.emp, qtd: 0, venda: 0, cmv: 0 };
  porProd[k].qtd += g.qtd; porProd[k].venda += g.venda; porProd[k].cmv += g.cmv;
});
var topProd = Object.keys(porProd).map(function (k) { return porProd[k]; })
  .sort(function (a, b) { return b.cmv - a.cmv; }).slice(0, MAX_PRODUTOS_EMAIL);
// ===== PLANILHA =====
function linhaPlanilha(o) {
  return { 'Mês': o.mes, 'Código': o.cod, 'Descrição': o.desc, 'Grupo': o.grupo, 'Subgrupo': o.subgrupo, 'Empresa': o.emp,
    'Quantidade vendida': o.qtd, 'Venda (R$)': o.venda, 'CMV (R$)': o.cmv, 'Lucro (R$)': o.lucro, 'Margem (%)': o.margem, 'Observação': o.obs };
}
function subtotal(mes, v, c, l) {
  return linhaPlanilha({ mes: mes, cod: '', desc: 'SUBTOTAL ' + mesBr(mes), grupo: '', subgrupo: '', emp: '', qtd: '', venda: r2(v), cmv: r2(c), lucro: r2(v - c), margem: pct(v - c, v), obs: '' });
}
function linhaTotal(mes, desc, emp, v, c) {
  return linhaPlanilha({ mes: mes, cod: '', desc: desc, grupo: '', subgrupo: '', emp: emp, qtd: '', venda: r2(v), cmv: r2(c), lucro: r2(v - c), margem: pct(v - c, v), obs: '' });
}
function montarPlanilha(comDetalhe) {
  var out = [];
  mesesOrdem.forEach(function (mes) {
    var emps = Object.keys(porEmp).sort();
    emps.forEach(function (emp) {
      var me = porMesEmp[mes + '|' + emp];
      if (!me) return;
      if (comDetalhe) {
        listaG.forEach(function (g) {
          if (g.mes !== mes || g.emp !== emp) return;
          out.push(linhaPlanilha({ mes: g.mes, cod: g.cod, desc: g.nome, grupo: g.grupo, subgrupo: g.subgrupo, emp: g.emp,
            qtd: r2(g.qtd), venda: r2(g.venda), cmv: r2(g.cmv), lucro: r2(g.venda - g.cmv), margem: pct(g.venda - g.cmv, g.venda),
            obs: g.semCusto ? g.semCusto + ' linha(s) sem custo no Gestor' : '' }));
        });
      }
      out.push(linhaTotal(mes, 'SUBTOTAL ' + mesBr(mes) + ' · ' + curta(emp), emp, me.venda, me.cmv));
    });
    out.push(linhaTotal(mes, 'SUBTOTAL ' + mesBr(mes) + ' · TODAS AS EMPRESAS', '', porMes[mes].venda, porMes[mes].cmv));
  });
  if (mesesOrdem.length > 1) {
    Object.keys(porEmp).sort().forEach(function (emp) {
      out.push(linhaTotal('TOTAL', 'TOTAL DO PERÍODO · ' + curta(emp), emp, porEmp[emp].venda, porEmp[emp].cmv));
    });
  }
  out.push(linhaTotal('TOTAL', 'TOTAL DO PERÍODO ' + br(ini) + ' a ' + br(fim) + ' · TODAS AS EMPRESAS', '', T.venda, T.cmv));
  return out;
}
var linhas = [], detalheIncluido = true;
if (!erro && linhasPeriodo > 0) {
  linhas = montarPlanilha(true);
  if (JSON.stringify(linhas).length > MAX_BYTES_DETALHE) { linhas = montarPlanilha(false); detalheIncluido = false; }
}
// ===== DADOS DO E-MAIL (o HTML é montado em "Montar E-mail do CMV", com o kit Waipe) =====
var avisosEmail = [];
function caixa(fundo, borda, cor, texto) { avisosEmail.push({ estilo: fundo === '#FFFBEB' ? 'alerta' : 'neutro', texto: texto }); return ''; }
var avisos = '';
if (!erro && linhasSemCusto > 0) avisos += caixa('#FFFBEB', '#FDE68A', '#92400E', '<b>Atenção:</b> ' + linhasSemCusto + ' linha(s) de venda vieram sem custo no Gestor. Nelas o CMV ficou zerado e o lucro está superestimado.') + '<br>';
if (!erro && dev.linhas > 0) avisos += caixa('#F9FAFB', '#E5E7EB', '#374151', dev.linhas + ' devolução(ões) no período, somando ' + brl(dev.valor) + ', não foram descontadas do CMV.') + '<br>';
if (!erro && baseIni && baseFim && (ini.getTime() < baseIni.getTime() || fim.getTime() > baseFim.getTime())) avisos += caixa('#FFFBEB', '#FDE68A', '#92400E', '<b>Atenção:</b> o período pedido sai da base carregada (' + br(baseIni) + ' a ' + br(baseFim) + '). Meses fora dessa faixa aparecem sem dados.') + '<br>';
if (!erro && !detalheIncluido) avisos += caixa('#F9FAFB', '#E5E7EB', '#374151', 'O detalhe por produto deste período ficou grande demais para a planilha. Ela traz só os subtotais mensais. Para o detalhe, peça um intervalo menor.') + '<br>';
var emailDados = erro ? null : {
  periodo: br(ini) + ' a ' + br(fim),
  vendas_fmt: brl(T.venda), cmv_fmt: brl(T.cmv), lucro_fmt: brl(T.lucro), margem_fmt: String(pct(T.lucro, T.venda)).replace('.', ',') + '%',
  por_empresa: empresasOrdem.map(function (e) {
    var p = porEmp[e], l = p.venda - p.cmv;
    return { empresa: curta(e), produtos: Object.keys(p.produtos).length, participacao: String(T.cmv > 0 ? r2(p.cmv / T.cmv * 100) : 0).replace('.', ',') + '%',
      vendas: brl(p.venda), cmv: brl(p.cmv), lucro: brl(l), margem: String(pct(l, p.venda)).replace('.', ',') + '%' };
  }),
  por_mes: mesesOrdem.map(function (m) {
    var p = porMes[m], l = p.venda - p.cmv;
    return { mes: mesBr(m), vendas: brl(p.venda), cmv: brl(p.cmv), lucro: brl(l), margem: String(pct(l, p.venda)).replace('.', ',') + '%' };
  }),
  maiores: topProd.map(function (x) { return { cod: x.cod, nome: x.nome, empresa: curta(x.emp), qtd: r2(x.qtd), vendas: brl(x.venda), cmv: brl(x.cmv) }; }),
  avisos: avisosEmail,
  processado: br(hoje)
};
// ===== SAÍDA =====
var resposta;
if (erro) {
  resposta = { erro: true, mensagem: erro };
} else {
  resposta = {
    periodo_inicial: iso(ini), periodo_final: iso(fim),
    vendas_total: r2(T.venda), cmv_total: r2(T.cmv), lucro_total: r2(T.lucro), margem_pct: pct(T.lucro, T.venda),
    por_mes: mesesOrdem.map(function (m) { var p = porMes[m]; return { mes: m, vendas: r2(p.venda), cmv: r2(p.cmv), lucro: r2(p.venda - p.cmv), margem_pct: pct(p.venda - p.cmv, p.venda) }; }),
    por_empresa: empresasOrdem.map(function (e) { var p = porEmp[e]; return { empresa: e, vendas: r2(p.venda), cmv: r2(p.cmv), lucro: r2(p.venda - p.cmv), margem_pct: pct(p.venda - p.cmv, p.venda), participacao_cmv_pct: T.cmv > 0 ? r2(p.cmv / T.cmv * 100) : 0, produtos: Object.keys(p.produtos).length }; }),
    linhas_consideradas: linhasPeriodo, linhas_sem_custo: linhasSemCusto,
    devolucoes_ignoradas: dev.linhas, devolucoes_valor: r2(dev.valor),
    detalhe_por_produto_incluido: detalheIncluido,
    base_inicio: baseIni ? iso(baseIni) : null, base_fim: baseFim ? iso(baseFim) : null
  };
}
return [{ json: { quantidade: erro ? 0 : linhasPeriodo, inicio: erro ? '' : br(ini), fim: erro ? '' : br(fim),
  linhas: linhas, email: emailDados, resposta: resposta, cmv_total_fmt: brl(T.cmv), vendas_total_fmt: brl(T.venda), lucro_total_fmt: brl(T.lucro) } }];

// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  nomeEmpresa: "NOME DA EMPRESA",
  rodape: "Mensagem automática do sistema comercial NOME DA EMPRESA."
};

// ============================================================
// PADRÃO DE E-MAIL WAIPE - copie este bloco para o node `code` que monta o e-mail.
// Desenho de referência: o consolidado do gestor do Guardião da Amostra Padrão (claro, com modo escuro automático).
// Marca "waipe" e empresa no topo, cartão branco com faixa escura, título com eyebrow dourado, indicadores
// em verde-oliva, tabelas claras e rodapé Londrisoft. Todo e-mail de agente do Waipe usa este kit.
// As funções devolvem linhas de tabela (<tr>) para dentro do cartão, exceto wpBadge/wpBarra/wpSeta, que devolvem
// HTML para colocar dentro de uma célula. wpPagina devolve o documento HTML completo.
// Compatível com o sandbox do Waipe Flow (sem toLocaleString, sem Intl).
// ============================================================
const WP_F = "font-family:Arial,Helvetica,sans-serif;";

function wpEsc(t) {
  if (t === null || t === undefined) return "";
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function wpNum(n) { return String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function wpMoeda(v) {
  const n = Math.round((Number(v) || 0) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-R$ " : "R$ ") + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}

// Estilos de destaque (badge, KPI e aviso): fundo, texto e borda. As cores do modo escuro ficam no <style> de wpPagina.
const WP_ESTILOS = {
  neutro: { bg: "#F9FAFB", cor: "#303030", borda: "#E5E7EB" },
  medio: { bg: "#F1F2EC", cor: "#5A6344", borda: "#E3E6D8" },
  forte: { bg: "#5A6344", cor: "#FFFFFF", borda: "#5A6344" },
  alerta: { bg: "#FEF3F2", cor: "#B42318", borda: "#FAD7D3" },
  ok: { bg: "#EEF8F1", cor: "#1E7A45", borda: "#CDEBD7" }
};

// Documento completo: marca e empresa, cartão (eyebrow, título, saudação, destaque), miolo (linhas) e rodapé.
// o: { preheader, empresa, rotuloDireita, eyebrow, titulo, heroEyebrow, heroValor, heroTam, heroSub, heroBarra,
//      heroNota, saudacao, subSaudacao, miolo, rodape: [linhas] }
// eyebrow/titulo são opcionais: sem eles, heroEyebrow vira o eyebrow do cartão.
function wpPagina(o) {
  const eyebrow = o.eyebrow || o.heroEyebrow || "";
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + wpEsc(o.titulo || eyebrow || o.empresa || "Waipe") + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wp-wrap{width:100%!important;max-width:100%!important;}.wp-pad{padding-left:16px!important;padding-right:16px!important;}.wp-kpi{display:block!important;width:100%!important;padding:0 0 8px 0!important;}.wp-hide{display:none!important;}.wp-h1{font-size:24px!important;line-height:30px!important;}.wp-hero{font-size:40px!important;line-height:44px!important;}}";
  h += "@media (prefers-color-scheme: dark){.wp-bg{background:#16181D!important;}.wp-card{background:#1F2229!important;border-color:#323743!important;}.wp-soft{background:#272B33!important;}.wp-t{color:#F3F4F6!important;}.wp-m{color:#A8AEBB!important;}.wp-bd{border-color:#323743!important;}.wp-eb{color:#D4B25A!important;}";
  h += "td[bgcolor='#303030']{background:#E5E7EB!important;}td[bgcolor='#303030'] a{color:#1F2229!important;}";
  h += "td[bgcolor='#F9FAFB']{background:#272B33!important;}td[bgcolor='#F1F2EC']{background:#2A2E24!important;}td[bgcolor='#E3E6D8']{background:#3A4030!important;}";
  h += "td[bgcolor='#FEF3F2']{background:#3A2422!important;}td[bgcolor='#EEF8F1']{background:#1F3A2C!important;}td[bgcolor='#F3F4F6']{background:#272B33!important;}";
  h += ".wp-c-medio{color:#C9CFB4!important;}.wp-c-neutro{color:#F3F4F6!important;}.wp-c-alerta{color:#FCA5A5!important;}.wp-c-ok{color:#86EFAC!important;}}";
  h += "</style></head>";
  h += "<body class='wp-bg' style='margin:0;padding:0;background:#F3F4F6;'>";
